func two_sum(nums, target) {
    var seen = dict();
    var i = 0;
    while (i < len(nums)) {
        var n = get(nums, i);
        var need = target - n;
        if (has(seen, need)) {
            return list(get(seen, need), i);
        }
        set(seen, n, i);
        i = i + 1;
    }
    return list();
}

func reverse(lst) {
    var out = list();
    var i = len(lst) - 1;
    while (i >= 0) {
        push(out, get(lst, i));
        i = i - 1;
    }
    return out;
}

func valid_parens(s) {
    var stack = list();
    var pairs = dict(")", "(", "]", "[", "}", "{");
    var i = 0;
    while (i < len(s)) {
        var c = get(s, i);
        if (c == "(" || c == "[" || c == "{") {
            push(stack, c);
        } else if (c == ")" || c == "]" || c == "}") {
            if (len(stack) == 0) { return false; }
            var top = pop(stack);
            if (top != get(pairs, c)) { return false; }
        }
        i = i + 1;
    }
    return len(stack) == 0;
}

func count_chars(s) {
    var s2 = lower(replace(s, " ", ""));
    var counts = dict();
    var i = 0;
    while (i < len(s2)) {
        var c = get(s2, i);
        if (has(counts, c)) {
            set(counts, c, get(counts, c) + 1);
        } else {
            set(counts, c, 1);
        }
        i = i + 1;
    }
    return counts;
}

func is_anagram(a, b) {
    var ca = count_chars(a);
    var cb = count_chars(b);
    if (len(keys(ca)) != len(keys(cb))) { return false; }
    var ks = keys(ca);
    var i = 0;
    while (i < len(ks)) {
        var k = get(ks, i);
        if (!has(cb, k)) { return false; }
        if (get(ca, k) != get(cb, k)) { return false; }
        i = i + 1;
    }
    return true;
}

func max_subarray(nums) {
    var best = get(nums, 0);
    var here = get(nums, 0);
    var i = 1;
    while (i < len(nums)) {
        var n = get(nums, i);
        if (here + n > n) { here = here + n; } else { here = n; }
        if (here > best) { best = here; }
        i = i + 1;
    }
    return best;
}

func move_zeros(nums) {
    var out = list();
    var zeros = 0;
    var i = 0;
    while (i < len(nums)) {
        var n = get(nums, i);
        if (n == 0) {
            zeros = zeros + 1;
        } else {
            push(out, n);
        }
        i = i + 1;
    }
    var z = 0;
    while (z < zeros) { push(out, 0); z = z + 1; }
    return out;
}

func pair_sum_sorted(nums, target) {
    var lo = 0;
    var hi = len(nums) - 1;
    while (lo < hi) {
        var s = get(nums, lo) + get(nums, hi);
        if (s == target) { return list(lo, hi); }
        if (s < target) { lo = lo + 1; } else { hi = hi - 1; }
    }
    return list();
}

func longest_unique(s) {
    var seen = dict();
    var lo = 0;
    var best = 0;
    var i = 0;
    while (i < len(s)) {
        var c = get(s, i);
        if (has(seen, c)) {
            if (get(seen, c) >= lo) { lo = get(seen, c) + 1; }
        }
        set(seen, c, i);
        if (i - lo + 1 > best) { best = i - lo + 1; }
        i = i + 1;
    }
    return best;
}

func max_profit(prices) {
    if (len(prices) == 0) { return 0; }
    var lo = get(prices, 0);
    var best = 0;
    var i = 1;
    while (i < len(prices)) {
        var p = get(prices, i);
        if (p < lo) { lo = p; }
        if (p - lo > best) { best = p - lo; }
        i = i + 1;
    }
    return best;
}

func climb(n) {
    if (n <= 2) { return n; }
    var a = 1;
    var b = 2;
    var i = 3;
    while (i <= n) {
        var c = a + b;
        a = b;
        b = c;
        i = i + 1;
    }
    return b;
}

