// Build a linked list from a list of values.
func to_ll(items) {
    var head = null;
    var i = len(items) - 1;
    while (i >= 0) {
        head = dict("val", get(items, i), "next", head);
        i = i - 1;
    }
    return head;
}

// Convert a linked list back to a list, for printing.
func ll_to_list(head) {
    var out = list();
    while (head != null) {
        push(out, get(head, "val"));
        head = get(head, "next");
    }
    return out;
}

